INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(41611, 'Job 18:18', 'Job', 18, 18, 'هغوئ د رڼا نه تيارې ته ديکه کړے شوى دى، او د دُنيا نه شړلے شوى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_18.mp3', '', 1761754199, 1761754199),
(41612, 'Job 18:19', 'Job', 18, 19, 'د هغوئ اولاد نشته، او د هغوئ د خاندان يو کس هم ژوندے پاتې شوے نۀ دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_19.mp3', '', 1761754199, 1761754199),
(41613, 'Job 18:20', 'Job', 18, 20, 'د نمرخاتۀ طرف نه واخله تر نمرپرېواتۀ پورې چې څوک هم د هغوئ د اَنجام نه خبريږى، نو د يرې نه لړزيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_20.mp3', '', 1761754199, 1761754199),
(41614, 'Job 18:21', 'Job', 18, 21, 'دوئ به وائى چې دا د بدعمله خلقو کور دے، د هغه چا څوک چې د خُدائ پاک نه منکر وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_21.mp3', '', 1761754199, 1761754199),
(41615, 'Psalms 80:1', 'Psalms', 80, 1, 'ای د اسراییلو شپونه ته مونږ ته غوږ ونیسه ای چې د یوسف د قبیلې کړې لارښوونه د رمې په څېر ته په خپل تخت ناست یې پاس په سر د اسماني مخلوق خپل جلال دې راښکاره کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_1.mp3', '', 1761754199, 1761754199),
(41616, 'Psalms 80:2', 'Psalms', 80, 2, 'ځان دې ښکاره خپل قبیلو ته کړه یعنې د افرایم، بنیامین او منسي قبیلې ته قدرت دې خپل مونږ ته راوښایه ته راشه او خلاص کړه مونږه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_2.mp3', '', 1761754199, 1761754199),
(41617, 'Psalms 80:3', 'Psalms', 80, 3, 'مونږ بېرته راوله خپل حال ته خدایه! په ورین تندي وګوره مونږ ته چې خلاص شو مونږه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_3.mp3', '', 1761754199, 1761754199),
(41618, 'Psalms 80:4', 'Psalms', 80, 4, 'ای مطلق قادر څښتنه خدایه ته به ترڅو پورې په قهر یې خپل قوم باندې او نه به اورې دعاګانې دې د خپلو خلکو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_4.mp3', '', 1761754199, 1761754199),
(41619, 'Psalms 80:5', 'Psalms', 80, 5, 'د ډوډۍ په ځای خوراک دې کړلو اوښکې د دوی په دوی دې وڅښلو د اوښکو ډک جام', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_5.mp3', '', 1761754199, 1761754199),
(41620, 'Psalms 80:6', 'Psalms', 80, 6, 'تا مونږ د خپلو ګاونډیانو د خندا کړلو وهي ملنډې دښمنان زمونږ په مونږ باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_6.mp3', '', 1761754199, 1761754199),
(41621, 'Psalms 80:7', 'Psalms', 80, 7, 'مونږ بېرته راوله خپل حال ته ای مطلق قادره خدایه! په ورین تندي وګوره مونږ ته چې خلاص شو مونږه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_7.mp3', '', 1761754199, 1761754199),
(41622, 'Psalms 80:8', 'Psalms', 80, 8, 'د تاک په شان دې خپل قوم وویسته د مصر څخه تا وشړل نور اقوام وکرل دوی دې د هغوی په ځای کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_8.mp3', '', 1761754199, 1761754199),
(41623, 'Psalms 80:9', 'Psalms', 80, 9, 'تا هغه ځمکه کړله پاکه ورته وځغلولې هغه ځای کې یې ریښې ژورې ورباندې ډکه شوله ټوله ځمکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_9.mp3', '', 1761754199, 1761754199),
(41624, 'Psalms 80:10', 'Psalms', 80, 10, 'شول غرونه ټول یې پټ په سیوري باندې د سبر غټې ونې راوستې شاخونو یې تر سیوري لاندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_10.mp3', '', 1761754199, 1761754199),
(41625, 'Psalms 80:11', 'Psalms', 80, 11, 'مدیترانې تر بحیرې پورې یې لاړې څانګې او شولې خپرې د فرات تر سینده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_11.mp3', '', 1761754199, 1761754199),
(41626, 'Psalms 80:12', 'Psalms', 80, 12, 'ولې دې وران کړل دېوالونه شاوخوا د هغه؟ اوس چې هرڅوک ورنه تېریږي نو راشکوي ترې انګور', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_12.mp3', '', 1761754199, 1761754199),
(41627, 'Psalms 80:13', 'Psalms', 80, 13, 'وحشي خوګان لاندې کوي یې تر‌پښو په کې څریږي ټول وحشي ځناور', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_13.mp3', '', 1761754199, 1761754199),
(41628, 'Psalms 80:14', 'Psalms', 80, 14, 'مطلق قادر خدایه راواړوه مخ! ته له اسمانه مونږ ته ښکته وګوره راشه او وساته خپل قوم دې خدایه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_14.mp3', '', 1761754199, 1761754199),
(41629, 'Psalms 80:15', 'Psalms', 80, 15, 'راشه او وساته نیالګی کوم چې کرلی دی تا دغه ځوان تاک چې قوي کړی دی تا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_15.mp3', '', 1761754199, 1761754199),
(41630, 'Psalms 80:16', 'Psalms', 80, 16, 'هغه ته اور دی اچولی دښمنانو زمونږ او راچپه کړی یې دی هغوی ته وګوره په قهر او برباد کړه هغوی!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_16.mp3', '', 1761754199, 1761754199),
(41631, 'Psalms 80:17', 'Psalms', 80, 17, 'نو ته قوي کړه هغه کس چې ورسره مینه کوې هغه څوک چې غوره کړی دی تا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_17.mp3', '', 1761754199, 1761754199),
(41632, 'Psalms 80:18', 'Psalms', 80, 18, 'بیا به هېڅکله تا نه مونږه خپل مخ نه اړوو ته مونږ ژوندي وساته چې ستا ستاینه وکړو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_18.mp3', '', 1761754199, 1761754199),
(41633, 'Psalms 80:19', 'Psalms', 80, 19, 'مونږ بېرته راوله خپل حال ته ای مطلق قادر څښتنه خدایه! په ورین تندي وګوره مونږ ته چې خلاص شو مونږه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms80_verse_19.mp3', '', 1761754199, 1761754199),
(41634, 'Ezekiel 46:1', 'Ezekiel', 46, 1, 'څښتن تعالی داسې وایي: «دنننۍ حوېلۍ ته د ختیځې خوا د ننوتلو دروازه باید د هفتې په شپږو کاري ورځو کې بنده وساتل شي، خو د سبت په ورځ او د نوې میاشتې په اختر کې باید خلاصه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_1.mp3', '', 1761754199, 1761754199),
(41635, 'Ezekiel 46:2', 'Ezekiel', 46, 2, 'مشر به د باندینۍ حوېلۍ نه د دروازې په لاره دنننۍ کوټې ته ننوځي او په داسې حال کې چې کاهنان د هغه سوځېدونکې نذرانه او د هغه د سلامتۍ نذرانې وړاندې کوي، هغه به د دروازې د چوکاټ سره ودریږي. هغه باید هلته د دروازې د خولې سره عبادت وکړي او بیا دباندې ووځي. دروازه باید تر ماښامه پورې ونه تړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_2.mp3', '', 1761754199, 1761754199),
(41636, 'Ezekiel 46:3', 'Ezekiel', 46, 3, 'د سبت په ورځ او د هرې نوې میاشتې په اختر کې باید د هېواد ټول خلک د هغې دروازې مخې ته څښتن ته سجده وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_3.mp3', '', 1761754199, 1761754199),
(41637, 'Ezekiel 46:4', 'Ezekiel', 46, 4, 'د سبت په ورځ به مشر څښتن ته شپږ وري او یو پسه چې په هغو کې کوم عیب نه وي د سوځېدونکو نذرانو په توګه وړاندې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_4.mp3', '', 1761754199, 1761754199),
(41638, 'Ezekiel 46:5', 'Ezekiel', 46, 5, 'هغه به د هر پسه سره لس کیلو‌ګرامه غلې دانې او د هر وري سره به دومره نذرانه چې څومره یې زړه غواړي، وړاندې کړي. د غلو دانو د نذرانو د هرې لس کیلو‌ګرامه نذرانې دپاره به څلور څلور لیتره د زیتونو تېل وړاندې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_5.mp3', '', 1761754199, 1761754199),
(41639, 'Ezekiel 46:6', 'Ezekiel', 46, 6, 'د نوې میاشتې په اختر کې به هغه یو خوسی، شپږ وري او یو پسه چې په ټولو کې کوم عیب نه وي، وړاندې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_6.mp3', '', 1761754199, 1761754199),
(41640, 'Ezekiel 46:7', 'Ezekiel', 46, 7, 'د هر غویي او هر پسه سره به لس کیلو‌ګرامه غلې دانې او د هر وري سره به دومره نذرانه چې مشر یې ورکولی شي، وړاندې کړي. د غلو دانو د نذرانو د هرې لس کیلو‌ګرامه نذرانې دپاره به څلور څلور لیتره د زیتونو تېل وړاندې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_7.mp3', '', 1761754199, 1761754199),
(41641, 'Ezekiel 46:8', 'Ezekiel', 46, 8, 'مشر باید د دروازې د دهلېز د لارې ننوځي او په همدې لاره باید ووځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_8.mp3', '', 1761754199, 1761754199),
(41642, 'Ezekiel 46:9', 'Ezekiel', 46, 9, 'کله چې خلک په کوم اختر کې د څښتن د عبادت دپاره راځي، نو څوک چې په شمالي دروازه باندې راننوځي، د عبادت کولو نه وروسته به په جنوبي دروازه باندې وځي او څوک چې په جنوبي دروازه راننوځي، په شمالي دروازه به وځي. په کومه لاره چې څوک ننوتلی وي، په هماغه لاره به نه وځي، بلکې په مخامخ لاره به وځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_9.mp3', '', 1761754199, 1761754199),
(41643, 'Ezekiel 46:10', 'Ezekiel', 46, 10, 'کله چې خلک راننوځي، نو مشر به راننوځي او کله چې هغوی لاړ شي، نو مشر به هم ځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_10.mp3', '', 1761754199, 1761754199),
(41644, 'Ezekiel 46:11', 'Ezekiel', 46, 11, 'په اخترونو او مذهبي جشنونو کې به د هر خوسي او د هر پسه سره لس کیلو‌ګرامه د غلو دانو نذرانه وړاندې کیږي او د هر وري سره چې عبادت کوونکی څومره غواړي، نو هغومره نذرانه به وړاندې کوي. د غلو دانو د نذرانو د هرې لس کیلو‌ګرامه نذرانې دپاره به څلور څلور لیتره د زیتونو تېل وړاندې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_11.mp3', '', 1761754199, 1761754199),
(41645, 'Ezekiel 46:12', 'Ezekiel', 46, 12, 'کله چې مشر وغواړي چې څښتن ته د خپلې خوښې نذرانه وړاندې کړي، که هغه سوځېدونکې نذرانه وي یا د سلامتۍ نذرانه وي، نو د هغه دپاره دې د دنننۍ حوېلۍ ختیځه دروازه خلاصه شي. بیا به هغه وکولای شي خپلې نذرانې وړاندې کړي، لکه څنګه چې یې د سبت په ورځ وړاندې کوي او کله چې هغه وځي، نو دروازه دې بېرته وتړل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_12.mp3', '', 1761754199, 1761754199),
(41646, 'Ezekiel 46:13', 'Ezekiel', 46, 13, 'څښتن وایي: «هر سهار باید یو وری چې یو کلن وي او کوم عیب په کې نه وي، د سوځېدونکې نذرانې په توګه دې څښتن ته وړاندې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_13.mp3', '', 1761754199, 1761754199),
(41647, 'Ezekiel 46:14', 'Ezekiel', 46, 14, 'همدارنګه هره ورځ سهار دې د دوه کیلو‌ګرامه اوړو نذرانه چې یو لیتر د زیتونو تېل ورسره ګډ وي، وړاندې شي. څښتن ته د دې نذرانې وړاندې کولو قوانین به تلپاتې قوانین وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_14.mp3', '', 1761754199, 1761754199),
(41648, 'Ezekiel 46:15', 'Ezekiel', 46, 15, 'وری، اوړه او د زیتونو تېل باید د تل دپاره هره ورځ سهار څښتن ته د سوځېدونکې نذرانې په توګه وړاندې شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_15.mp3', '', 1761754199, 1761754199),
(41649, 'Ezekiel 46:16', 'Ezekiel', 46, 16, 'څښتن تعالی داسې وایي: «که چېرې مشر د خپلې ځمکې نه یو څه ځمکه په خپلو زامنو کې یو زوی ته د سوغات په توګه ورکړي، نو دا ځمکه به د هغه د کورنۍ په جایداد کې د همدې زوی برخه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_16.mp3', '', 1761754199, 1761754199),
(41650, 'Ezekiel 46:17', 'Ezekiel', 46, 17, 'خو که چېرې مشر د خپلې ځمکې نه څه ځمکه د خپلو خدمتګارانو څخه کوم یو ته ورکړي، نو دا ځمکه به د ازادۍ د ورکولو تر کاله پورې د هغه سره وي او بیا به دا ځمکه بېرته مشر ته ورکول کیږي. یوازې هغه او د هغه زامن کولای شي چې د هغې ځمکې تلپاتې خاوندان اوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_17.mp3', '', 1761754199, 1761754199),
(41651, 'Ezekiel 46:18', 'Ezekiel', 46, 18, 'مشر باید د خلکو نه د هغوی جایداد په زور وانخلي. هغه چې خپلو زامنو ته کومه ځمکه ورکوي، نو باید د خپلې ځمکې نه یې ورکړي، ترڅو زما د قوم څخه هیڅوک هم د خپلې ځمکې څخه ونه ویستل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_18.mp3', '', 1761754199, 1761754199),
(41652, 'Ezekiel 46:19', 'Ezekiel', 46, 19, 'بیا هغه سړي زه د ننوتلو د لارې نه چې د شمالي دروازې په څنګ کې وه، د کاهنانو هغو سپېڅلو کوټو ته چې شمال خواته مخامخ وې، بوتلم. هلته یې ماته د دې کوټو د لوېدیځې برخې په پای کې یو ځای وښود', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_19.mp3', '', 1761754199, 1761754199),
(41653, 'Ezekiel 46:20', 'Ezekiel', 46, 20, 'او هغه ماته وویل: «دا هغه ځای دی چې کاهنان دې په کې د تاوان او د ګناه د نذرانو غوښه وایشوي او د اوړو نذرانې دې پخې کړي، ترڅو هېڅ کوم سپېڅلی شی باندینۍ حوېلۍ ته یونه وړل شي چې خلکو ته زیان ورسوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_20.mp3', '', 1761754199, 1761754199),
(41654, 'Ezekiel 46:23', 'Ezekiel', 46, 23, 'دننه د هر یو ګردچاپېره د تیږو دېوال ؤ، د دې دېوال څنګ ته نغري جوړ شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_23.mp3', '', 1761754199, 1761754199),
(41655, 'Ezekiel 46:24', 'Ezekiel', 46, 24, 'هغه سړي ماته وویل: «دا هغه پخلنځایونه دي چې د څښتن د کور خدمتګاران دې په کې د قربانیو غوښې چې خلک یې راوړي، وایشوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel46_verse_24.mp3', '', 1761754199, 1761754199),
(41656, 'Ecclesiastes 7:1', 'Ecclesiastes', 7, 1, 'له قیمتي عطرو نه نېک نامي غوره ده او د زېږېدو له ورځې نه د مړینې ورځ بهتره ده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_1.mp3', '', 1761754199, 1761754199),
