(41666, 'Ecclesiastes 7:11', 'Ecclesiastes', 7, 11, 'حکمت انسان ته چې د لمر د روښنایۍ لاندې اوسیږي د یو میراث په شان ښه او ګټور دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_11.mp3', '', 1761754199, 1761754199),
(41667, 'Ecclesiastes 7:12', 'Ecclesiastes', 7, 12, 'ځکه حکمت د انسان پر سر سیوری دی لکه څنګه چې پیسې د هغه پر سر سیوری دی خو د حکمت د پېژندلو ګټه دا ده چې د خپل خاوند د ژوند ساتنه کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_12.mp3', '', 1761754199, 1761754199),
(41668, 'Ecclesiastes 7:13', 'Ecclesiastes', 7, 13, 'د خدای کار ته په غور سره پام وکړه: څوک هغه شی سمولی شي چې خدای کوږ کړی دی؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_13.mp3', '', 1761754199, 1761754199),
(41669, 'Ecclesiastes 7:14', 'Ecclesiastes', 7, 14, 'د نېکمرغۍ په وخت کې خوشحالي وکړه خو د بدمرغۍ په وخت کې دې ته پام وکړه: چې نېکمرغي او بدمرغي دواړه د خدای له خوا دي ترڅو راتلونکې پېښې له انسان نه پټې وساتي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_14.mp3', '', 1761754199, 1761754199),
(41670, 'Ecclesiastes 7:15', 'Ecclesiastes', 7, 15, 'ما دا دوه شیان د خپل لوګي او پوکي په شان ژوند په موده کې لیدلي دي: هغه نېکان چې د خپل صداقت سره سره بیاهم له وخت نه وړاندې مړه کیږي او هغه بدکاران چې د خپل شرارت سره سره بیاهم اوږد ژوند کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_15.mp3', '', 1761754199, 1761754199),
(41671, 'Ecclesiastes 7:16', 'Ecclesiastes', 7, 16, 'نه ډېر نېک او صادق اوسه او نه هم ځان ډېر پوه او هوښیار وښایه هسې نه چې ځان برباد کړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_16.mp3', '', 1761754199, 1761754199),
(41672, 'Ecclesiastes 7:17', 'Ecclesiastes', 7, 17, 'نه ځان بدکارۍ ته تسلیم کړه او نه هم کم عقل اوسه هسې نه چې د خپل ټاکلي وخت نه وړاندې مړ شې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_17.mp3', '', 1761754199, 1761754199),
(41673, 'Ecclesiastes 7:18', 'Ecclesiastes', 7, 18, 'څومره ښه ده چې له هغو دواړو نه یو خبرداری په پام کې ونیسې خو هغه بل هم له پامه ونه غورځوې ځکه څوک چې له خدایه وېریږي نو هغه دواړه له پامه نه غورځوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_18.mp3', '', 1761754199, 1761754199),
(41674, 'Ecclesiastes 7:19', 'Ecclesiastes', 7, 19, 'حکمت یو پوه او هوښیار سړي ته د ښار له لسو مشرانو څخه زیات واک او اختیار ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_19.mp3', '', 1761754199, 1761754199),
(41675, 'Ecclesiastes 7:20', 'Ecclesiastes', 7, 20, 'په حقیقت کې، هېڅوک په نړۍ کې داسې صادق نه دی چې تل نېک کار وکړي او هېڅکله بدي ونه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_20.mp3', '', 1761754199, 1761754199),
(41676, 'Ecclesiastes 7:21', 'Ecclesiastes', 7, 21, 'نو خلک چې څه وایي هغه په زړه کې مه نیسه، هسې نه چې ته د خپل غلام هغه ښکنځلې واورې چې تا پسې یې کوي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_21.mp3', '', 1761754199, 1761754199),
(41677, 'Ecclesiastes 7:22', 'Ecclesiastes', 7, 22, 'ځکه ته په خپل زړه کې ښه پوهېږې چې تا هم ډېر ځلې نورو ته ښکنځلې کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_22.mp3', '', 1761754199, 1761754199),
(41678, 'Ecclesiastes 7:23', 'Ecclesiastes', 7, 23, 'دا ټول شیان ما په خپل حکمت سره وازمایل. نو له ځان سره مې وویل: «راځه په دې شیانو باندې هم ځان پوه کړم،» خو دا زما له پوهې نه بهر ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_23.mp3', '', 1761754199, 1761754199),
(41679, 'Ecclesiastes 7:24', 'Ecclesiastes', 7, 24, 'هرڅه چې اوس موجود دي هغه د انسان له پوهې نه بهر او د هغې پوهېدل ډېر ژور دی. انسان د ژوند دا پټ راز څنګه پیدا کولای شي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_24.mp3', '', 1761754199, 1761754199),
(41680, 'Ecclesiastes 7:25', 'Ecclesiastes', 7, 25, 'نو بیا ما په دې اړه فکر وکړ ترڅو په هرڅه باندې ځان پوه کړم، هغه وڅېړم او حکمت او د ژوند پټ راز پیدا کړم. همدا شان ما دا هڅه هم وکړه چې په دې ځان پوه کړم چې بدکاري څومره کم‌عقلتوب او حماقت څومره جهالت دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_25.mp3', '', 1761754199, 1761754199),
(41681, 'Ecclesiastes 7:26', 'Ecclesiastes', 7, 26, 'نو یو وار بیا پوه شوم چې هغه ښځه له مرګ څخه ډېره ترخه ده کومه چې د زړه نیت یې د ښکاري د دام او لاسونه یې د زندان د زنځیرونو په څېر دي. هرڅوک چې خدای راضي او خوشحاله کړي، نو له هغې څخه ځان ژغوري، خو ګناهکار د هغې په دام کې رانښلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_26.mp3', '', 1761754199, 1761754199),
(41682, 'Ecclesiastes 7:27', 'Ecclesiastes', 7, 27, 'نو څېړونکي وویل: «وګوره، زه د ژوند د پټ راز د څېړنو په موده کې ورو ورو دې نتیجې ته ورسېدم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_27.mp3', '', 1761754199, 1761754199),
(41683, 'Ecclesiastes 7:28', 'Ecclesiastes', 7, 28, 'چې دغه پټ راز چې زما زړه په وار وار غوښتل هغه پیدا کړي، تر‌اوسه نه دی پیدا شوی. ما د زرو کسانو په منځ کې یوازې یو نېک سړی پیدا کړی دی او د دې ټولو په منځ کې مې حتی یوه نېکه ښځه هم پیدا نه کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_28.mp3', '', 1761754199, 1761754199),
(41684, 'Ecclesiastes 7:29', 'Ecclesiastes', 7, 29, 'نو ما یوازې دا حقیقت پیدا کړ چې خدای انسان نېک پیدا کړی دی خو هغه د ډېرو نورو نقشو په لټه کې دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes7_verse_29.mp3', '', 1761754199, 1761754199),
(41685, 'Isaiah 28:1', 'Isaiah', 28, 1, 'افسوس د سامرې د ښار په حال! ځکه چې د اسراییلو د نشه یي مشرانو د پرتمین تاج په شان دی. هغه د یوې حاصلخېزې درې په سر پروت دی، خو ښایست به یې لکه د ګلانو په شان مړاوی شي. دا د هغو خلکو دپاره ویاړ دی چې په شرابو نشه کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_1.mp3', '', 1761754199, 1761754199),
(41686, 'Isaiah 28:2', 'Isaiah', 28, 2, 'ګورئ، څښتن داسې زورور کسان لري چې حملې ته تیار دي، دا کسان به د یو زورور توفان، ږلۍ، باران او سېلاب په شان راشي او ښار به تباه او له منځه لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_2.mp3', '', 1761754199, 1761754199),
(41687, 'Isaiah 28:3', 'Isaiah', 28, 3, 'بیا به سامره چې د نشه یي مشرانو غرور او د یو پرتمین تاج په شان دی، تر پښو لاندې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_3.mp3', '', 1761754199, 1761754199),
(41688, 'Isaiah 28:4', 'Isaiah', 28, 4, 'بیا د دې مړاوي کېدونکي ګل ښکلا به چې د یوې حاصلخېزې درې په سر کې دی، داسې له منځه لاړه شي لکه د انځرو د لومړنۍ مېوې په شان چې څنګه پخه شي، وشکول شي او وخوړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_4.mp3', '', 1761754199, 1761754199),
(41689, 'Isaiah 28:5', 'Isaiah', 28, 5, 'په هغه ورځ به مطلق قادر څښتن د خپلو ژوندي پاتې شویو خلکو دپاره لکه د یو پرتمین تاج په شان وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_5.mp3', '', 1761754199, 1761754199),
(41690, 'Isaiah 28:6', 'Isaiah', 28, 6, 'څښتن به هغو کسانو ته چې د قاضیانو په توګه دنده لري د عدالت او انصاف وس او توان ورکړي او هغو کسانو ته چې د حملې په وخت کې د ښار له دروازو ساتنه کوي، زړورتیا ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_6.mp3', '', 1761754199, 1761754199),
(41691, 'Isaiah 28:7', 'Isaiah', 28, 7, 'حتی تر دې پورې چې کاهنان او نبیان هم دومره نشه دي او دومره ډېر شراب یې څښلي چې په لاره کاږه واږه روان دي. نبیان په هغه رویاګانو نه پوهیږي چې څښتن ورته رالېږلي او هم کاهنان د قضاوت کولو په وخت کې زنګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_7.mp3', '', 1761754199, 1761754199),
(41692, 'Isaiah 28:8', 'Isaiah', 28, 8, 'د هغوی دسترخوان د کانګو او چټلیو څخه ډک دي او هېڅ یو پاک ځای په کې نه لیدل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_8.mp3', '', 1761754199, 1761754199),
(41693, 'Isaiah 28:9', 'Isaiah', 28, 9, 'هغوی زما نه شکایت کوي او وایي: «دا سړی چې مونږ ته زده کړه راکوي، څوک دی؟ د هغه پیغام ته څوک اړ دی؟ د هغه تعلیم او پیغام یوازې د هغو ماشومانو دپاره ښه دي چې همدا اوس له تي نه بېل شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_9.mp3', '', 1761754199, 1761754199),
(41694, 'Isaiah 28:10', 'Isaiah', 28, 10, 'په رښتیا هغه تش د بې معنی لغتونو اواز وباسي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_10.mp3', '', 1761754199, 1761754199),
(41695, 'Isaiah 28:11', 'Isaiah', 28, 11, 'ګورئ، که تاسو زما خبرو ته غوږ ونه نیسئ، نو څښتن به د پردیو خلکو په وسیله په عجیبه ژبه له تاسو سره خبرې وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_11.mp3', '', 1761754199, 1761754199),
(41696, 'Isaiah 28:12', 'Isaiah', 28, 12, 'څښتن غوښتل چې تاسو ستړو ته ارامي درکړي، خو تاسو د هغه د منلو څخه ډډه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_12.mp3', '', 1761754199, 1761754199),
(41697, 'Isaiah 28:13', 'Isaiah', 28, 13, 'نو له دې امله به تاسو ته د څښتن کلام لکه د بې معنی لغتونو د اواز په شان وي. نو هغه وخت چې هر قدم اخلئ، وبه ښويېږئ. تاسو به ټپیان شئ، په دام کې به راګېر شئ او اسیران به شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_13.mp3', '', 1761754199, 1761754199),
(41698, 'Isaiah 28:14', 'Isaiah', 28, 14, 'ای د اورشلیم ملنډې وهونکو حاکمانو، د څښتن کلام ته پاملرنه وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_14.mp3', '', 1761754199, 1761754199),
(41699, 'Isaiah 28:15', 'Isaiah', 28, 15, 'تاسو وایئ چې له مرګ سره مو تړون کړی دی او د مړو له دنیا سره مو لاس یو کړی دی. تاسو ډاډه یئ چې کله په تاسو باندې د سیلاب په شان مصیبت راشي نو تاسو به بچ شئ، ځکه چې تاسو فکر کوئ چې کولای شئ په ټګۍ او دروغو ځان خوندي وساتئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_15.mp3', '', 1761754199, 1761754199),
(41700, 'Isaiah 28:16', 'Isaiah', 28, 16, 'نو په دې خاطر دا هغه څه دي چې څښتن تعالی یې وایي: «زه د صهیون بنیاد په یوې غوره، ازمایل شوې او قیمتي تیږه ږدم. نو په هغه باندې به دا ټکي لیکل شوي وي: ‹هرڅوک چې ایمان راوړي، هغه نه وارخطا کیږي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_16.mp3', '', 1761754199, 1761754199),
(41701, 'Isaiah 28:17', 'Isaiah', 28, 17, 'انصاف به د هغه بنیاد دپاره د اندازه کولو رسۍ وي او صداقت به د هغه شاقول وي.» توفان او ږلۍ به ستاسو د پناه ځایونه چې د دروغو په بنیاد ایښودل شوي دي، وران کړي او سېلابونه به هغه له منځه یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_17.mp3', '', 1761754199, 1761754199),
(41702, 'Isaiah 28:18', 'Isaiah', 28, 18, 'هغه تړون چې تاسو له مرګ سره کړی ؤ هغه به ړنګ شي او د مړو له دنیا سره مو چې لاس یو کړی دی هغه به باطل شي. کله چې په تاسو باندې د سیلاب په شان مصیبت راشي، نو تاسو به د پښو لاندې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_18.mp3', '', 1761754199, 1761754199),
(41703, 'Isaiah 28:19', 'Isaiah', 28, 19, 'هغه مصیبت به په ورځ یا شپه او یا هرکله چې راشي، هغه به ونه شئ زغملای. که چېرې په دې پیغام باندې پوه شئ، تاسو ته به ډېره وېره پیدا شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_19.mp3', '', 1761754199, 1761754199),
(41704, 'Isaiah 28:20', 'Isaiah', 28, 20, 'تاسو به د هغه کس په شان یئ چې په دې متل کې یاد شوی دی: «د هغه کټ دومره لنډ ؤ چې پښې یې په کې نه شواې غزولی او کمپله یې هم دومره لنډه وه چې ځان یې په کې نه شو پټولی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_20.mp3', '', 1761754199, 1761754199),
(41705, 'Isaiah 28:21', 'Isaiah', 28, 21, 'څښتن به په قهر راپاڅیږي او جګړه به وکړي، لکه څنګه چې یې د فراسیم په غره او د جبعون په دره کې کړې وه. نو هغه به عجیبه او غیر عادي کارونه سرته ورسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_21.mp3', '', 1761754199, 1761754199),
(41706, 'Isaiah 28:22', 'Isaiah', 28, 22, 'نو بیا زه چې تاسو ته کوم خبرداری درکوم په هغه باندې ملنډې مه وهئ. که ملنډې مو ووهلې، نو خلاصېدل به درته ډېر ګران شي. ځکه ما د مطلق قادر څښتن خدای پرېکړه واورېدله چې هغه به ټول وطن وران کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_22.mp3', '', 1761754199, 1761754199),
(41707, 'Isaiah 28:23', 'Isaiah', 28, 23, 'واورئ، ماته غوږ ونیسئ او زما خبرو ته پام وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_23.mp3', '', 1761754199, 1761754199),
(41708, 'Isaiah 28:24', 'Isaiah', 28, 24, 'هېڅ بزګر په خپلو پټیو کې په پرله پسې توګه قلبه نه کوي او نه یې د کرلو دپاره هواروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_24.mp3', '', 1761754199, 1761754199),
(41709, 'Isaiah 28:25', 'Isaiah', 28, 25, 'خو کله چې هغه ځمکه د کرلو دپاره تیاره شوه، په دې وخت کې په ځمکه کې تخمونه کري. هغه پوهیږي چې د بوټو تخمونه لکه شبت او ځيره چېرته وشیندل شي، د غنمو او اوربشو تخمونه په قطارونو کې او د غلو دانو نور تخمونه د پټیو په څنډه کې وکرل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_25.mp3', '', 1761754199, 1761754199),
(41710, 'Isaiah 28:26', 'Isaiah', 28, 26, 'بزګر په خپله دنده پوهیږي، ځکه چې د هغه خدای ورته سمه لارښودنه کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_26.mp3', '', 1761754199, 1761754199);